#!/usr/bin/env bash
# Provision a running WLED board over HTTP with everything build flags can't
# bake: config/cfg.json (HUB75 panel + 2D layout), config/2d-gaps.json (the
# LEDs behind the mask, generated by gfx/make-gap.py), the GIFs in
# config/gifs/ and config/presets.json (generated by bin/gen-presets.sh).
#
# Only what differs is pushed. One GET of /edit?list= names every file on the
# board with its size and one GET of /json/cfg gives the live config, so an
# up-to-date board costs two small requests, no uploads and no reboot.
#
# Usage: ./provision.sh [options] [host]
#   [host]                 Board IP or hostname (default: 4.3.2.1, the WLED setup-AP address;
#                          use the board's LAN IP or wled-xxxxxx.local once it has joined WiFi)
#   -f, --file <cfg.json>  Config to apply (default: config/cfg.json)
#   -F, --force            Push everything, including files the board already has
#   -u, --upload           Replace the board's cfg.json with the file instead of merging
#                          (fresh boards only — discards any settings not in the file)
#   -c, --config-only      Only apply cfg.json and the gap file (skip GIFs and presets)
#   -g, --presets-only     Only upload GIFs and presets.json (no cfg change, no reboot)
#   -G, --no-gap           Leave the board's gap file alone
#       --prune            Delete files the board has and the repo does not
#   -n, --no-reboot        Skip the reboot (matrix, and the gap file, only apply after one)
#   -v, --verify-only      Change nothing; only check the board against the repo files
#   -P, --pin <pin>        Settings PIN, if the board has one
#   -h, --help             Show this help
#
# Default mode POSTs cfg.json to /json/cfg: WLED merges it into the live config
# field by field and saves it, so it is safe on an already-configured board.
# GIFs, presets.json and the gap file go through /upload (presets.json replaces
# the board's). The gap file has to be called 2d-gaps.json on the board: no
# config field points at it, WLED just reads that name while building the 2D
# pixel map, which it does at boot — so a new gap file, like a matrix change,
# only takes effect after the reboot.
#
# --prune removes whatever is left on the board that config/gifs/ and config/
# do not account for — a GIF that has been renamed or dropped, most often. It
# spares cfg.json, wsec.json, presets.json and 2d-gaps.json, and nothing else:
# a ledmap or a custom palette uploaded by hand is not in the repo either, and
# will go. -v shows what it would delete without deleting anything.

set -euo pipefail

REPO_DIR=$(cd "$(dirname "$0")/.." && pwd)
CFG=$REPO_DIR/config/cfg.json
GAPS=$REPO_DIR/config/2d-gaps.json
GIF_DIR=$REPO_DIR/config/gifs
PRESETS=$REPO_DIR/config/presets.json
DEFAULT_HOST=4.3.2.1   # WLED-AP address of an unconfigured board
HOST=""
MODE=merge
DO_CFG=1
DO_GAP=1
DO_PRESETS=1
REBOOT=1
VERIFY_ONLY=0
FORCE=0
PRUNE=0
PIN=""

while [[ $# -gt 0 ]]; do
  case "$1" in
    -f|--file)         CFG="$2"; shift 2 ;;
    -F|--force)        FORCE=1; shift ;;
    -u|--upload)       MODE=upload; shift ;;
    -c|--config-only)  DO_PRESETS=0; shift ;;
    -g|--presets-only) DO_CFG=0; DO_GAP=0; REBOOT=0; shift ;;
    -G|--no-gap)       DO_GAP=0; shift ;;
    --prune)           PRUNE=1; shift ;;
    -n|--no-reboot)    REBOOT=0; shift ;;
    -v|--verify-only)  VERIFY_ONLY=1; shift ;;
    -P|--pin)          PIN="$2"; shift 2 ;;
    -h|--help)         sed -n '2,40{s/^# \{0,1\}//p;}' "$0"; exit 0 ;;
    -*) echo "Unknown option: $1 (see --help)" >&2; exit 1 ;;
    *)  [[ -z "$HOST" ]] || { echo "Unexpected argument: $1" >&2; exit 1; }; HOST="$1"; shift ;;
  esac
done

die() { echo "ERROR: $*" >&2; exit 1; }
fsize() { stat -c %s "$1" 2>/dev/null || stat -f %z "$1"; }
HOST=${HOST:-$DEFAULT_HOST}
command -v curl >/dev/null || die "curl is required"
command -v python3 >/dev/null || die "python3 is required"
if [[ $DO_CFG -eq 1 ]]; then
  [[ -f "$CFG" ]] || die "config file not found: $CFG"
  python3 -m json.tool "$CFG" >/dev/null 2>&1 || die "$CFG is not valid JSON"
fi
# WLED drops a gap array shorter than the matrix without a word, so check the
# length here against the panel the config describes.
if [[ $DO_GAP -eq 1 && $DO_CFG -eq 1 ]]; then
  if [[ -f "$GAPS" ]]; then
    python3 - "$GAPS" "$CFG" <<'GAPCHECK' || die "$GAPS is not a usable gap file"
import json, sys
try: gaps = json.load(open(sys.argv[1]))
except Exception as e: sys.exit(f"  not valid JSON: {e}")
if not isinstance(gaps, list): sys.exit("  a gap file is a flat JSON array")
bad = sorted({v for v in gaps if v not in (-1, 0, 1)})
if bad: sys.exit(f"  values outside -1/0/1: {bad[:5]}")
led = json.load(open(sys.argv[2])).get("hw", {}).get("led", {})
need = sum(p.get("w", 0) * p.get("h", 0) for p in led.get("matrix", {}).get("panels") or [])
if need and len(gaps) < need:
    sys.exit(f"  {len(gaps)} entries for a {need}-pixel matrix; WLED ignores a short one silently")
GAPCHECK
  else
    DO_GAP=0
    echo "Gap:    config/2d-gaps.json missing — skipping (gfx/generate-all.sh writes it)"
  fi
fi
GIFS=()
if [[ $DO_PRESETS -eq 1 ]]; then
  while IFS= read -r f; do GIFS+=("$f"); done < <(ls "$GIF_DIR"/*.gif 2>/dev/null | sort || true)
  if [[ -f "$PRESETS" ]]; then
    python3 -m json.tool "$PRESETS" >/dev/null 2>&1 || die "$PRESETS is not valid JSON"
  elif [[ ${#GIFS[@]} -gt 0 ]]; then
    die "config/presets.json missing — run bin/gen-presets.sh first"
  fi
fi

HOST=${HOST#http://}; HOST=${HOST%/}
BASE="http://$HOST"
CURL=(curl -sS --connect-timeout 5 --max-time 60)
json_field() { python3 -c 'import json,sys; d=json.load(sys.stdin); print(eval(sys.argv[1], {"d": d}))' "$1" 2>/dev/null; }
FAILS=0

# upload <local file> <remote name>: multipart POST to /upload
upload() {
  local resp
  resp=$("${CURL[@]}" -F "data=@$1;filename=/$2" "$BASE/upload") || die "upload of $2 failed"
  case "$resp" in
    *"File Uploaded"*|*"Config restore ok"*) ;;
    *) die "unexpected response uploading $2: $resp (settings PIN? pass -P <pin>)" ;;
  esac
}

# remove <remote name>: WLED deletes through the same handler that lists.
# --data-urlencode matters: a name like astryx-assemble+45.gif has to reach it
# as %2B, or the + arrives as a space and the delete misses.
remove_remote() {
  local resp
  resp=$("${CURL[@]}" --get --data-urlencode "func=delete" --data-urlencode "path=/$1" \
         "$BASE/edit") || die "delete of $1 failed"
  case "$resp" in
    *"File deleted"*) ;;
    *) die "unexpected response deleting $1: $resp (settings PIN? pass -P <pin>)" ;;
  esac
}

# The board's whole filesystem in one request: /edit?list=/ answers with
# [{"name","type","size"}, ...]. Cheaper than fetching files back to compare,
# and it is what lets an unchanged file be skipped instead of re-uploaded.
FILE_TABLE=""
HAVE_LIST=0
read_listing() {
  local raw
  raw=$("${CURL[@]}" "$BASE/edit?list=/" 2>/dev/null) || return 1
  FILE_TABLE=$(printf '%s' "$raw" | python3 -c '
import json, sys
try: files = json.load(sys.stdin)
except Exception: sys.exit(1)
if not isinstance(files, list): sys.exit(1)
for f in files:
    if isinstance(f, dict) and f.get("type") == "file":
        print(f'"'"'{f["name"].lstrip("/")} {f.get("size", 0)}'"'"')
') || return 1
  HAVE_LIST=1
}
# board_size <name>: bytes the board holds for that file, "" if it has none or
# there is no listing. Must succeed either way — it is read through $( ), and a
# non-zero status there takes the whole script down under set -e.
board_size() {
  [[ $HAVE_LIST -eq 1 ]] || return 0
  awk -v n="$1" '$1 == n { print $2; exit }' <<<"$FILE_TABLE"
}

# --- Preflight ----------------------------------------------------------------
INFO=$("${CURL[@]}" "$BASE/json/info") || die "cannot reach $BASE (is the board on the network?)"
echo "Board:  $(json_field 'd.get("name","?")' <<<"$INFO") — WLED $(json_field 'd.get("ver","?")' <<<"$INFO") ($(json_field 'd.get("arch","?")' <<<"$INFO"))"
if [[ -n "$PIN" ]]; then
  # any JSON POST carrying "pin" unlocks PIN-protected endpoints (/upload and /edit included)
  "${CURL[@]}" -o /dev/null -H 'Content-Type: application/json' --data "{\"pin\":\"$PIN\"}" "$BASE/json/state" || die "PIN unlock request failed"
fi
read_listing || echo "Note:   the board did not answer /edit?list= — nothing can be skipped or checked by size"

# --- What differs? ------------------------------------------------------------
# Sizes come from the listing above; a file the board already holds at the same
# size is left alone unless -F. Everything to push is collected here first so
# the run can say up front what it is going to do, and do nothing at all when
# there is nothing to do.
PUSH_LOCAL=(); PUSH_NAME=(); PUSH_WHY=()
plan() {  # plan <local file> <remote name>
  local have; have=$(board_size "$2"); local want; want=$(fsize "$1")
  if [[ $FORCE -eq 0 && -n "$have" && "$have" == "$want" ]]; then return; fi
  PUSH_LOCAL+=("$1"); PUSH_NAME+=("$2")
  if [[ -z "$have" ]]; then PUSH_WHY+=("new")
  elif [[ "$have" != "$want" ]]; then PUSH_WHY+=("$have -> $want bytes")
  else PUSH_WHY+=("forced"); fi
}
if [[ $DO_PRESETS -eq 1 ]]; then
  for g in "${GIFS[@]}"; do plan "$g" "$(basename "$g")"; done
  [[ -f "$PRESETS" ]] && plan "$PRESETS" "presets.json"
fi
[[ $DO_GAP -eq 1 ]] && plan "$GAPS" "2d-gaps.json"

# Everything the repo accounts for, read off disk rather than off the flags:
# -c must not make the GIFs look like strangers and have --prune eat them.
STALE=()
if [[ $PRUNE -eq 1 && $HAVE_LIST -eq 1 ]]; then
  KEEP=$'cfg.json\nwsec.json\npresets.json\n2d-gaps.json'
  while IFS= read -r f; do [[ -n "$f" ]] && KEEP+=$'\n'$(basename "$f"); done \
    < <(ls "$GIF_DIR"/*.gif 2>/dev/null || true)
  while read -r name _; do
    [[ -n "$name" ]] && ! grep -qxF "$name" <<<"$KEEP" && STALE+=("$name")
  done <<<"$FILE_TABLE"
fi

# The config is compared the same way: read once, merged only if it differs.
CFG_DIFFERS=0
LIVE=""
if [[ $DO_CFG -eq 1 ]]; then
  LIVE=$("${CURL[@]}" "$BASE/json/cfg") || die "cannot read /json/cfg"
  if [[ $FORCE -eq 1 || $MODE = upload ]]; then
    CFG_DIFFERS=1
  else
    LIVE_JSON="$LIVE" python3 - "$CFG" >/dev/null 2>&1 <<'PY' || CFG_DIFFERS=1
import json, os, sys
want = json.load(open(sys.argv[1]))
live = json.loads(os.environ["LIVE_JSON"])
def subset(w, l):
    if isinstance(w, dict): return isinstance(l, dict) and all(subset(v, l.get(k)) for k, v in w.items())
    if isinstance(w, list): return isinstance(l, list) and len(w) == len(l) and all(subset(a, b) for a, b in zip(w, l))
    return w == l
sys.exit(0 if subset(want, live) else 1)
PY
  fi
fi

if [[ $VERIFY_ONLY -eq 0 && ${#PUSH_LOCAL[@]} -eq 0 && $CFG_DIFFERS -eq 0 && ${#STALE[@]} -eq 0 ]]; then
  echo "Up to date: every file and the panel config already match the repo (-F to push anyway)."
  exit 0
fi

# --- Push ---------------------------------------------------------------------
REBOOTED=0
NEEDS_REBOOT=0
if [[ $VERIFY_ONLY -eq 0 ]]; then
  if [[ ${#PUSH_LOCAL[@]} -eq 0 ]]; then
    echo "Files:  nothing to upload"
  else
    for i in "${!PUSH_LOCAL[@]}"; do
      echo "Uploading ${PUSH_NAME[$i]} ($(( $(fsize "${PUSH_LOCAL[$i]}") / 1024 )) KB, ${PUSH_WHY[$i]}) ..."
      upload "${PUSH_LOCAL[$i]}" "${PUSH_NAME[$i]}"
      # a new gap file is only read while the 2D map is built, i.e. at boot
      [[ "${PUSH_NAME[$i]}" == "2d-gaps.json" ]] && NEEDS_REBOOT=1
    done
  fi

  if [[ $DO_CFG -eq 1 && $CFG_DIFFERS -eq 1 ]]; then
    echo "Config: $CFG"
    if [[ $MODE = upload ]]; then
      echo "Replacing /cfg.json on the board (upload mode) ..."
      upload "$CFG" "cfg.json"
      echo "Uploaded; the board reboots on its own."
      REBOOTED=1
    else
      echo "Merging into the live config (/json/cfg) ..."
      BODY=$(python3 - "$CFG" "$PIN" <<'PY'
import json, sys
d = json.load(open(sys.argv[1]))
if sys.argv[2]: d["pin"] = sys.argv[2]
print(json.dumps(d))
PY
)
      HTTP=$("${CURL[@]}" -o /tmp/provision_resp.$$ -w '%{http_code}' -H 'Content-Type: application/json' --data "$BODY" "$BASE/json/cfg") || die "POST /json/cfg failed"
      RESP=$(cat /tmp/provision_resp.$$); rm -f /tmp/provision_resp.$$
      [[ "$HTTP" == 401 ]] && die "board rejected the request (settings PIN?) — pass -P <pin>"
      [[ "$HTTP" == 200 && "$RESP" == *'"success":true'* ]] || die "unexpected response from /json/cfg (HTTP $HTTP): $RESP"
      echo "Merged and saved."
      NEEDS_REBOOT=1
    fi
  elif [[ $DO_CFG -eq 1 ]]; then
    echo "Config: already matches the board"
  fi

  if [[ $REBOOTED -eq 0 && $NEEDS_REBOOT -eq 1 ]]; then
    if [[ $REBOOT -eq 1 ]]; then
      echo "Rebooting ..."
      "${CURL[@]}" -o /dev/null -H 'Content-Type: application/json' --data '{"rb":true}' "$BASE/json/state" || die "reboot request failed"
      REBOOTED=1
    else
      echo "Not rebooting (-n); HUB75/matrix and gap changes take effect after the next reboot."
    fi
  fi
  if [[ $REBOOTED -eq 1 ]]; then
    echo -n "Waiting for the board to come back "
    sleep 1
    for i in $(seq 1 60); do
      if "${CURL[@]}" --max-time 2 -o /dev/null "$BASE/json/info" 2>/dev/null; then echo " up."; break; fi
      echo -n "."; sleep 1
      [[ $i -eq 60 ]] && { echo; die "board did not come back within 60 s"; }
    done
  fi
  if [[ ${#STALE[@]} -gt 0 ]]; then
    for name in "${STALE[@]}"; do
      echo "Deleting /$name ($(( $(board_size "$name") / 1024 )) KB, not in the repo) ..."
      remove_remote "$name"
    done
  fi

  # anything uploaded or deleted makes the listing read at the start stale, and
  # the listing is what the checks below compare against
  [[ ${#PUSH_LOCAL[@]} -gt 0 || ${#STALE[@]} -gt 0 ]] && { read_listing || true; }
fi

# --- Verify -------------------------------------------------------------------
# Files are checked against the listing, not fetched back: reading 400 KB of
# GIFs off the board to compare their sizes cost more than writing them did.
if [[ $PRUNE -eq 1 && $VERIFY_ONLY -eq 1 ]]; then
  if [[ ${#STALE[@]} -eq 0 ]]; then
    echo "Prune:  nothing on the board that the repo does not have"
  else
    echo "Prune:  would delete ${#STALE[@]} file(s): ${STALE[*]}"
  fi
fi
echo "Verifying:"
if [[ $DO_CFG -eq 1 ]]; then
  [[ $REBOOTED -eq 1 || -z "$LIVE" ]] && { LIVE=$("${CURL[@]}" "$BASE/json/cfg") || die "cannot read back /json/cfg"; }
  LIVE_JSON="$LIVE" python3 - "$CFG" <<'PY' || FAILS=$((FAILS + 1))
import json, os, sys
want = json.load(open(sys.argv[1])).get("hw", {}).get("led", {})
live = json.loads(os.environ["LIVE_JSON"]).get("hw", {}).get("led", {})
ok = True
def subset(w, l):  # every value in the file must appear on the board; the board may carry extra keys (e.g. panel b/r/v/s)
    if isinstance(w, dict): return isinstance(l, dict) and all(subset(v, l.get(k)) for k, v in w.items())
    if isinstance(w, list): return isinstance(l, list) and len(w) == len(l) and all(subset(a, b) for a, b in zip(w, l))
    return w == l
def show(label, w, l):
    global ok
    same = subset(w, l); ok &= same
    print(f"  {'OK  ' if same else 'DIFF'} {label}: board={l}" + ("" if same else f"  wanted={w}"))
for i, ins in enumerate(want.get("ins", [])):
    l = (live.get("ins") or [{}])[i] if i < len(live.get("ins") or []) else {}
    show(f"output {i} type", ins.get("type"), l.get("type"))
    show(f"output {i} pin/params", ins.get("pin"), l.get("pin"))
if "matrix" in want:
    show("matrix panels", want["matrix"].get("mpc"), live.get("matrix", {}).get("mpc"))
    show("matrix layout", want["matrix"].get("panels"), live.get("matrix", {}).get("panels"))
sys.exit(0 if ok else 1)
PY
fi
check_file() {  # check_file <local file> <remote name>
  local want have
  want=$(fsize "$1"); have=$(board_size "$2")
  if [[ $HAVE_LIST -eq 0 ]]; then echo "  ?    /$2 (no file list from the board)"; return; fi
  if [[ "$have" == "$want" ]]; then echo "  OK   /$2 ($want bytes)"
  else echo "  DIFF /$2: board has ${have:-no such file}, local $want bytes"; FAILS=$((FAILS + 1)); fi
}
[[ $DO_GAP -eq 1 ]] && check_file "$GAPS" "2d-gaps.json"
if [[ $DO_PRESETS -eq 1 ]]; then
  for g in "${GIFS[@]}"; do check_file "$g" "$(basename "$g")"; done
  if [[ -f "$PRESETS" ]]; then
    # presets.json is the one file whose contents decide what plays, and it is
    # small, so this one is read back in full rather than trusted by size.
    REMOTE_PRESETS=$("${CURL[@]}" "$BASE/presets.json") || { echo "  DIFF /presets.json: cannot read back"; FAILS=$((FAILS + 1)); REMOTE_PRESETS=""; }
    if [[ -n "$REMOTE_PRESETS" ]]; then
      REMOTE_JSON="$REMOTE_PRESETS" python3 - "$PRESETS" <<'PY' || FAILS=$((FAILS + 1))
import json, os, sys
want = {k: v.get("n") for k, v in json.load(open(sys.argv[1])).items() if k != "0"}
have = {k: v.get("n") for k, v in json.loads(os.environ["REMOTE_JSON"]).items() if k != "0"}
if want == have: print(f"  OK   /presets.json ({len(want)} presets: {', '.join(want.values())})"); sys.exit(0)
print(f"  DIFF /presets.json: board has {have}, wanted {want}"); sys.exit(1)
PY
    fi
  fi
fi
if [[ $FAILS -eq 0 ]]; then echo "Provisioning complete."; else echo "WARNING: $FAILS check(s) differ from the repo (see DIFF lines)."; exit 2; fi
